import{z as d,x as A,o,c as p,q as l,j as r,D as e,d as t,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"对比学习与 InfoNCE","description":"","frontmatter":{"title":"对比学习与 InfoNCE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/contrastive-infonce.md","filePath":"llm/contrastive-infonce.md","lastUpdated":1791413859000}'),m={name:"llm/contrastive-infonce.md"};function B(f,a,_,C,c,h){const E=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=l('<h1 id="对比学习与-infonce" tabindex="-1">对比学习与 InfoNCE <a class="header-anchor" href="#对比学习与-infonce" aria-label="Permalink to &quot;对比学习与 InfoNCE&quot;">​</a></h1><div class="epigraph"><p>把正确配对的向量拉近、把批内其它配对推远，温度缩放的 softmax 就是 InfoNCE。嵌入空间的余弦意义从这里来，不是从语言模型的 MLM 头来。</p><footer>—— van den Oord 等 CPC 中的 InfoNCE；句向量实践见 [池化](/llm/embedding-pooling)</footer></div><p><a href="/llm/analogical-prompting">上一课</a>把「推理链与提示」课序收在类比提示：让模型先自生成相关例题再解当前题，把选题从人工少样本挪到测试时生成。本课打开「嵌入训练与检索工程」，从生成器转向检索：生成器之外需要可缓存的向量。主干已有池化与 <a href="/llm/clip">CLIP</a> 双塔；本课把损失钉成 InfoNCE，作为后课难负例、Matryoshka、指令嵌入的共同目标。缺口不是再讲 Transformer，而是：<strong>句向量要有度量目标</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/embedding-pooling">均值池化</a>给出 \\(z\\)，若仍只做 MLM，余弦没有语义。检索要把查询 \\(q\\) 与相关文档 \\(d^+\\) 拉近、与无关 \\(d^-\\) 推远。生成式交叉熵做不到「一批里谁更近」。需要一个在向量上的分类损失：把正对当成正确类，把批内其它文档当成负类。</p><p>van den Oord 等人把互信息下界写成 InfoNCE。CLIP、SimCLR、Sentence-BERT / 检索双塔用的都是同一族：温度缩放点积 + 交叉熵。后课默认「对比训练」指这一族，不再把三元组合页损失当默认。</p><p><span class="marginnote">对比学习的口诀就一句：相似的靠近，不相似的开远。它不教模型「答案是什么」，只教它「谁和谁是一对」——判卷标准从「写出正确答案」变成「在一堆候选里认出正确答案」。</span></p><p><span class="marginnote">本课的嵌入是检索向量，不是输入层 token embedding，也不是权重量化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>批内 \\(N\\) 个正对 \\((q_i,d_i)\\)，相似度 \\(s_{ij}=z_{q_i}^\\top z_{d_j}/\\tau\\)（向量已 \\(\\ell_2\\) 归一则是余弦）。对称 InfoNCE 常对行与列各做一次 softmax 交叉熵，与 CLIP 课同一形式。\\(\\tau\\) 过小会把损失变成几乎只看最难负例；过大则梯度平坦。双塔共享或不共享编码器，查询与文档可以非对称（短问对长文）。</p>',10)),(o(),r(s,null,{default:e(()=>[i(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E5%A1%94%22%5D%20--%3E%20S%5B%22%E6%B8%A9%E5%BA%A6%E7%BC%A9%E6%94%BE%E7%82%B9%E7%A7%AF%22%5D%0A%20%20D%5B%22%E6%96%87%E6%A1%A3%E5%A1%94%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20CE%5B%22%E6%89%B9%E5%86%85%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20CE%20--%3E%20Z%5B%22%E5%8F%AF%E4%BD%99%E5%BC%A6%E6%A3%80%E7%B4%A2%E7%9A%84%20z%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"InfoNCE 把「谁是正例」当成 \\(N\\) 类分类，负例越多，对互信息的下界越紧，经验上批要大。梯度来自正对不够近、以及与高分负例不够远。因此负例的难度决定空间有多细——下一课专门挖难负例。没有负例（只有正对回归）会塌缩：所有向量走向同一点，余弦无意义。",-1)),a[5]||(a[5]=n("p",null,"「当成 \\(N\\) 类分类」具体怎么发生，可以按一条查询的视角画出来：",-1)),(o(),r(s,null,{default:e(()=>[i(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20q_1%22%5D%20--%3E%20S%5B%22%E4%B8%8E%E6%89%B9%E5%86%85%20N%20%E4%B8%AA%E6%96%87%E6%A1%A3%E7%AE%97%E7%9B%B8%E4%BC%BC%E5%BA%A6%22%5D%0A%20%20D1%5B%22d_1%3A%E6%AD%A3%E7%A1%AE%E9%85%8D%E5%AF%B9%22%5D%20--%3E%20S%0A%20%20D2%5B%22d_2%E2%80%A6d_N%3A%E6%89%B9%E5%86%85%E8%B4%9F%E4%BE%8B%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20CE%5B%22softmax%20%E5%90%8E%E5%BA%94%E5%BD%93%E9%80%89%E4%B8%AD%20d_1%22%5D%0A%20%20CE%20--%3E%20G%5B%22%E6%8B%89%E8%BF%91%20q_1%20%E4%B8%8E%20d_1%2C%E6%8E%A8%E8%BF%9C%E5%85%B6%E4%BD%99%20N-1%20%E4%B8%AA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字感受温度 \\(\\tau\\) 的作用：两个相似度 3.0 和 2.5，除以 \\(\\tau=0.05\\) 后变成 60 与 50，softmax 几乎把全部赌注押在最难的那个负例上；除以 \\(\\tau=1\\) 则差距温和，梯度摊给所有负例。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>批内负例假设「同一批里其它文档与 \\(q_i\\) 无关」。语义近邻碰巧同批会变成假负例，把同义文档推远。下一课用挖掘与去假负缓解。生成式 RAG 的阅读器仍是 LM；本课只训检索器。</p><p><span class="marginnote">「假负例」可以这样理解：批里混进了一篇和查询同义的文章，损失函数却按「无关」去推远它。模型学到的不是「分辨相关与无关」，而是「见到相近的就推开」——这是检索质量莫名变差的常见暗因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>句向量的余弦来自 InfoNCE 一类对比损失，不是来自 MLM。</li><li>温度、批大小与是否对称决定梯度结构。</li><li>批内假负例是结构缺陷，交给难负例课。</li><li>出处：van den Oord 等 CPC / InfoNCE；CLIP；Reimers &amp; Gurevych Sentence-BERT。</li></ul>',6))])}const N=d(m,[["render",B]]);export{D as __pageData,N as default};
